def test_issubclass_with_non_types():
    from boltons.typeutils import issubclass
    assert issubclass('hi', 'friend') is False
    assert issubclass(42, int) is False
    assert issubclass(int, 42) is False

    class MyClass(object):
        pass

    assert issubclass(MyClass, object) is True
    assert issubclass(MyClass, int) is False

def test_get_all_subclasses_recursive():
    from boltons.typeutils import get_all_subclasses

    class Base:
        pass

    class Child(Base):
        pass

    class GrandChild(Child):
        pass

    subclasses = get_all_subclasses(Base)
    assert Child in subclasses
    assert GrandChild in subclasses
